/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `species_data` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'Internal plant identifier used as plantId',
  `scientific_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Accepted scientific name',
  `vernacular_name` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Common/vernacular name(s)',
  `family` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Plant family',
  `establishment_means` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g. native, introduced, uncertain',
  `degree_of_establishment` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g. native, naturalised, adventive',
  `match_key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Normalised scientific-name matching key',
  `risk_rating` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '2022 Advisory List risk rating, NULL means no exact assessment',
  `vba_record_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'City of Monash VBA matching record count',
  `vba_most_recent_year` smallint unsigned DEFAULT NULL COMMENT 'Most recent City of Monash VBA record year',
  `inat_record_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'iNaturalist record count, not required by Iteration 1 API',
  `inat_most_recent_date` datetime DEFAULT NULL COMMENT 'Most recent iNaturalist record date, not required by Iteration 1 API',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_species_data_match_key` (`match_key`),
  UNIQUE KEY `uk_species_data_scientific_name` (`scientific_name`),
  KEY `idx_species_data_vernacular_name` (`vernacular_name`(191))
) ENGINE=InnoDB AUTO_INCREMENT=881 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
